import{_ as t,o as i,c as s,a2 as n}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Directives Éthiques des Deux Âmes","description":"","frontmatter":{},"headers":[],"relativePath":"fr/58-双魂伦理准则.md","filePath":"fr/58-双魂伦理准则.md","lastUpdated":1789183869000}'),r={name:"fr/58-双魂伦理准则.md"};function d(o,e,a,l,m,u){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="directives-ethiques-des-deux-ames" tabindex="-1">Directives Éthiques des Deux Âmes <a class="header-anchor" href="#directives-ethiques-des-deux-ames" aria-label="Permalink to &quot;Directives Éthiques des Deux Âmes&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>58</td></tr><tr><td>Module</td><td>Races et Formes de Vie</td></tr><tr><td>Mots clés</td><td>Éthique des deux âmes, droits de la personnalité, dignité de l&#39;âme, équilibre des intérêts, examen éthique</td></tr></tbody></table><h2 id="i-la-problematique-de-l-ethique-des-deux-ames" tabindex="-1">I. La Problématique de l&#39;Éthique des Deux Âmes <a class="header-anchor" href="#i-la-problematique-de-l-ethique-des-deux-ames" aria-label="Permalink to &quot;I. La Problématique de l&#39;Éthique des Deux Âmes&quot;">​</a></h2><p>La problématique de l&#39;éthique des deux âmes est le problème éthique fondamental que la Civilisation Symbiotique de l&#39;Ancre doit résoudre face aux Entités de Remplacement Sombres (voir <em>57-黑暗置换体起源与本质</em>). Lorsqu&#39;un seul corps contient deux âmes indépendantes — l&#39;âme maîtresse d&#39;origine et l&#39;âme de remplacement sombre — une série de problèmes éthiques profonds surgit :</p><ul><li>Les deux âmes possèdent-elles des droits de la personnalité indépendants ?</li><li>Les droits de l&#39;âme maîtresse d&#39;origine priment-ils sur ceux de l&#39;âme de remplacement sombre ?</li><li>Est-il moral d&#39;annihiler l&#39;âme de remplacement sombre pour protéger l&#39;âme maîtresse d&#39;origine ?</li><li>Lorsque les intérêts des deux âmes entrent en conflit, comment doivent-ils être pesés ?</li><li>La société a-t-elle l&#39;obligation d&#39;investir des ressources pour sauver les âmes maîtresses d&#39;origine remplacées par l&#39;obscurité ?</li><li>L&#39;âme de remplacement sombre a-t-elle un « droit à l&#39;existence » ?</li></ul><p>Ces problèmes n&#39;ont pas de réponses simples ; des principes éthiques systématiques doivent être établis pour guider la pratique. Les Directives Éthiques des Deux Âmes sont précisément le document normatif formulé en réponse à ces problèmes, et constituent le fondement éthique de l&#39;identification, du traitement et de la disposition des Entités de Remplacement Sombres.</p><h2 id="ii-principes-fondamentaux-de-l-ethique-des-deux-ames" tabindex="-1">II. Principes Fondamentaux de l&#39;Éthique des Deux Âmes <a class="header-anchor" href="#ii-principes-fondamentaux-de-l-ethique-des-deux-ames" aria-label="Permalink to &quot;II. Principes Fondamentaux de l&#39;Éthique des Deux Âmes&quot;">​</a></h2><p>Les Directives Éthiques des Deux Âmes établissent les six principes fondamentaux suivants comme pierre angulaire de valeur pour traiter les problèmes des deux âmes :</p><table tabindex="0"><thead><tr><th>Principe</th><th>Connotation</th></tr></thead><tbody><tr><td>Principe de dignité de l&#39;âme</td><td>Chaque âme dotée d&#39;une conscience indépendante jouit d&#39;une dignité inhérente et ne doit pas être arbitrairement annihilée ou asservie</td></tr><tr><td>Principe de priorité de l&#39;âme d&#39;origine</td><td>Dans les conflits des deux âmes, les droits légitimes de l&#39;âme maîtresse d&#39;origine priment sur ceux de l&#39;âme de remplacement sombre, car l&#39;hôte d&#39;origine est le propriétaire légitime du corps</td></tr><tr><td>Principe de moindre préjudice</td><td>Lors du traitement des problèmes des deux âmes, l&#39;option causant le moins de préjudice à toutes les parties concernées doit être choisie, en évitant autant que possible l&#39;annihilation des âmes</td></tr><tr><td>Principe de proportionnalité</td><td>Les mesures prises doivent correspondre au degré de risque de l&#39;entité des deux âmes ; le traitement excessif est interdit</td></tr><tr><td>Principe de consentement éclairé</td><td>Lorsque l&#39;âme maîtresse d&#39;origine peut exprimer sa volonté, les décisions majeures impliquant le corps et l&#39;âme de l&#39;hôte d&#39;origine doivent obtenir son consentement</td></tr><tr><td>Principe d&#39;effort maximal de sauvetage</td><td>La société a l&#39;obligation de faire tous les efforts raisonnables pour sauver les âmes maîtresses d&#39;origine remplacées par l&#39;obscurité et ne doit pas abandonner à la légère</td></tr></tbody></table><h2 id="iii-determination-des-droits-de-la-personnalite-des-deux-ames" tabindex="-1">III. Détermination des Droits de la Personnalité des Deux Âmes <a class="header-anchor" href="#iii-determination-des-droits-de-la-personnalite-des-deux-ames" aria-label="Permalink to &quot;III. Détermination des Droits de la Personnalité des Deux Âmes&quot;">​</a></h2><p>Le problème premier de l&#39;éthique des deux âmes est la détermination des droits de la personnalité des deux âmes. Ces Directives établissent les règles de détermination suivantes :</p><h3 id="i-droits-de-la-personnalite-de-l-ame-maitresse-d-origine" tabindex="-1">(I) Droits de la personnalité de l&#39;âme maîtresse d&#39;origine <a class="header-anchor" href="#i-droits-de-la-personnalite-de-l-ame-maitresse-d-origine" aria-label="Permalink to &quot;(I) Droits de la personnalité de l&#39;âme maîtresse d&#39;origine&quot;">​</a></h3><p>L&#39;âme maîtresse d&#39;origine est le propriétaire légitime du corps, et ses droits de la personnalité sont pleinement reconnus et protégés :</p><ol><li>L&#39;âme maîtresse d&#39;origine jouit de tous les droits fondamentaux conférés par la Constitution Symbiotique, y compris le droit à la vie, le droit à l&#39;intégrité corporelle, le droit à la santé, le droit à la dignité personnelle, etc.</li><li>L&#39;âme maîtresse d&#39;origine a le pouvoir décisionnel final sur son propre corps ; lorsqu&#39;elle peut exprimer sa volonté, toute disposition majeure impliquant le corps doit obtenir le consentement de l&#39;hôte d&#39;origine.</li><li>Les droits et intérêts légitimes de l&#39;âme maîtresse d&#39;origine, tels que les droits de propriété, les droits d&#39;identité et les relations sociales, sont protégés par la loi et ne sont pas perdus en raison du remplacement sombre.</li><li>L&#39;âme maîtresse d&#39;origine a le droit de recevoir un sauvetage et un soutien sociaux, y compris le traitement de purification, l&#39;aide juridique, le soutien psychologique, etc.</li><li>Même si elle est profondément supprimée, les droits de la personnalité de l&#39;âme maîtresse d&#39;origine subsistent ; elle ne doit pas être déclarée morte ni privée de droits.</li></ol><h3 id="ii-droits-de-la-personnalite-de-l-ame-de-remplacement-sombre" tabindex="-1">(II) Droits de la personnalité de l&#39;âme de remplacement sombre <a class="header-anchor" href="#ii-droits-de-la-personnalite-de-l-ame-de-remplacement-sombre" aria-label="Permalink to &quot;(II) Droits de la personnalité de l&#39;âme de remplacement sombre&quot;">​</a></h3><p>La détermination des droits de la personnalité de l&#39;âme de remplacement sombre est relativement complexe ; ces Directives adoptent la position de « reconnaissance limitée » :</p><table tabindex="0"><thead><tr><th>Stade de développement</th><th>Détermination des droits de la personnalité</th><th>Portée des droits</th></tr></thead><tbody><tr><td>Période d&#39;érosion énergétique (Premier stade)</td><td>Pas de personnalité indépendante</td><td>Une âme indépendante ne s&#39;est pas encore formée ; pas de droits de la personnalité indépendants</td></tr><tr><td>Période de contamination de l&#39;âme (Deuxième stade)</td><td>Pas de personnalité indépendante</td><td>Encore un état contaminé de l&#39;âme maîtresse d&#39;origine ; pas de droits de la personnalité indépendants</td></tr><tr><td>Période de formation des deux âmes (Troisième stade)</td><td>Droits de la personnalité limités</td><td>Possède une conscience indépendante préliminaire, jouit des droits fondamentaux de dignité de l&#39;âme, mais ne jouit pas des droits de contrôle du corps ni des droits de citoyenneté complets</td></tr><tr><td>Période de domination sombre (Quatrième stade)</td><td>Droits de la personnalité limités</td><td>Possède une conscience complètement indépendante, jouit des droits de dignité de l&#39;âme et du droit d&#39;être traité avec respect, mais en raison de son danger, ses droits sont soumis à des restrictions nécessaires</td></tr><tr><td>Période de remplacement complet (Cinquième stade)</td><td>Droits de la personnalité complets (mais comme existence hostile)</td><td>L&#39;hôte d&#39;origine a péri, l&#39;âme sombre devient la seule âme du corps, avec des droits de la personnalité complets, mais en raison de son comportement hostile, des mesures coercitives incluant l&#39;annihilation peuvent être prises conformément à la loi</td></tr></tbody></table><h3 id="iii-contenu-specifique-des-droits-de-la-personnalite-limites" tabindex="-1">(III) Contenu spécifique des droits de la personnalité limités <a class="header-anchor" href="#iii-contenu-specifique-des-droits-de-la-personnalite-limites" aria-label="Permalink to &quot;(III) Contenu spécifique des droits de la personnalité limités&quot;">​</a></h3><p>Les droits de la personnalité limités dont jouit l&#39;âme de remplacement sombre aux troisième et quatrième stades comprennent :</p><ol><li><strong>Droit à la dignité de l&#39;âme</strong> : ne doit pas être traitée avec insulte, abus ou torture ; le respect fondamental doit être maintenu même dans le contrôle et la disposition.</li><li><strong>Droit à l&#39;annihilation sans douleur</strong> : s&#39;il est finalement décidé d&#39;annihiler l&#39;âme de remplacement sombre, une méthode sans douleur et rapide doit être adoptée pour réduire sa souffrance.</li><li><strong>Droit d&#39;expression</strong> : dans des conditions sûres et contrôlables, l&#39;âme de remplacement sombre a le droit d&#39;exprimer sa volonté et sa position, mais son expression n&#39;a pas de force juridique contraignante.</li><li><strong>Droit d&#39;être entendue</strong> : lors de décisions majeures impliquant l&#39;âme de remplacement sombre, son opinion doit être entendue dans une mesure raisonnable.</li></ol><p>L&#39;âme de remplacement sombre ne jouit pas des droits suivants : droits de contrôle du corps, liberté de mouvement, droits politiques de citoyen, droits de propriété (les biens de l&#39;hôte d&#39;origine appartiennent à l&#39;hôte d&#39;origine) et droits de reproduction (pour empêcher la propagation des lignées sombres).</p><h2 id="iv-regles-de-ponderation-des-conflits-d-interets-des-deux-ames" tabindex="-1">IV. Règles de Pondération des Conflits d&#39;Intérêts des Deux Âmes <a class="header-anchor" href="#iv-regles-de-ponderation-des-conflits-d-interets-des-deux-ames" aria-label="Permalink to &quot;IV. Règles de Pondération des Conflits d&#39;Intérêts des Deux Âmes&quot;">​</a></h2><p>Lorsque les intérêts de l&#39;âme maîtresse d&#39;origine et de l&#39;âme de remplacement sombre entrent en conflit, ils sont pondérés selon les règles suivantes :</p><h3 id="i-types-de-conflits-et-regles-de-ponderation" tabindex="-1">(I) Types de conflits et règles de pondération <a class="header-anchor" href="#i-types-de-conflits-et-regles-de-ponderation" aria-label="Permalink to &quot;(I) Types de conflits et règles de pondération&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type de conflit</th><th>Règle de pondération</th></tr></thead><tbody><tr><td>Conflit de droits de survie (la survie d&#39;une partie est conditionnée par la disparition de l&#39;autre)</td><td>Le droit de survie de l&#39;âme maîtresse d&#39;origine prime ; lorsque la coexistence est impossible, la survie de l&#39;hôte d&#39;origine est protégée en premier</td></tr><tr><td>Conflit de droits de contrôle du corps</td><td>L&#39;âme maîtresse d&#39;origine a le droit de contrôle final sur le corps ; le droit de contrôle du corps de l&#39;âme sombre est strictement limité</td></tr><tr><td>Conflit de droits d&#39;expression</td><td>L&#39;expression de l&#39;âme maîtresse d&#39;origine a force juridique contraignante ; l&#39;expression de l&#39;âme sombre ne sert que de référence</td></tr><tr><td>Conflit de droits de propriété</td><td>Le corps et les biens appartiennent à l&#39;hôte d&#39;origine ; l&#39;âme sombre n&#39;a pas de droits de propriété</td></tr><tr><td>Conflit de droits de choix de traitement</td><td>L&#39;âme maîtresse d&#39;origine a le droit de choisir d&#39;accepter ou non le traitement de purification ; l&#39;âme sombre n&#39;a pas le droit de l&#39;empêcher</td></tr><tr><td>Conflit de méthode de disposition</td><td>Pour les dispositions impliquant l&#39;annihilation de l&#39;âme sombre, la volonté de l&#39;âme maîtresse d&#39;origine joue un rôle décisif (mais doit subir un examen éthique)</td></tr></tbody></table><h3 id="ii-respect-et-limitation-de-la-volonte-de-l-hote-d-origine" tabindex="-1">(II) Respect et limitation de la volonté de l&#39;hôte d&#39;origine <a class="header-anchor" href="#ii-respect-et-limitation-de-la-volonte-de-l-hote-d-origine" aria-label="Permalink to &quot;(II) Respect et limitation de la volonté de l&#39;hôte d&#39;origine&quot;">​</a></h3><p>Lorsque l&#39;âme maîtresse d&#39;origine peut exprimer sa volonté, la volonté de l&#39;hôte d&#39;origine doit être pleinement respectée, avec les exceptions suivantes :</p><ol><li>Les volontés de l&#39;hôte d&#39;origine qui nuisent manifestement à la sécurité publique ou aux droits et intérêts légitimes d&#39;autrui ne sont pas protégées.</li><li>Les expressions de volonté faites par l&#39;hôte d&#39;origine sous l&#39;influence de l&#39;âme sombre qui ne sont pas authentiques n&#39;ont pas de validité juridique.</li><li>Si l&#39;hôte d&#39;origine choisit volontairement de fusionner avec l&#39;âme sombre, un examen éthique strict et une évaluation des risques doivent être menés pour confirmer que l&#39;existence après la fusion ne constituera pas une menace pour la société.</li><li>Si l&#39;hôte d&#39;origine choisit volontairement d&#39;abandonner le traitement et d&#39;accepter le remplacement complet par l&#39;âme sombre, la société doit intervenir et conseiller, mais si l&#39;hôte d&#39;origine est pleinement lucide et confirme à plusieurs reprises, le droit de décision autonome de l&#39;hôte d&#39;origine doit finalement être respecté (c&#39;est une zone grise éthique nécessitant un examen au cas par cas).</li></ol><h2 id="v-mecanisme-d-examen-ethique-des-deux-ames" tabindex="-1">V. Mécanisme d&#39;Examen Éthique des Deux Âmes <a class="header-anchor" href="#v-mecanisme-d-examen-ethique-des-deux-ames" aria-label="Permalink to &quot;V. Mécanisme d&#39;Examen Éthique des Deux Âmes&quot;">​</a></h2><p>Pour garantir que le traitement des problèmes des deux âmes respecte les principes éthiques, l&#39;État établit un mécanisme d&#39;examen éthique des deux âmes :</p><h3 id="i-comite-d-examen-ethique" tabindex="-1">(I) Comité d&#39;examen éthique <a class="header-anchor" href="#i-comite-d-examen-ethique" aria-label="Permalink to &quot;(I) Comité d&#39;examen éthique&quot;">​</a></h3><ul><li><strong>Composition</strong> : composé d&#39;éthiciens, de juristes, de scientifiques de la vie, de cultivateurs, de représentants des races étrangères et de représentants du public ; les experts ayant une expérience de recherche ou de traitement des Entités de Remplacement Sombres ne doivent pas représenter moins d&#39;un tiers.</li><li><strong>Fonctions</strong> : examiner et trancher les problèmes éthiques majeurs impliquant les deux âmes, y compris les décisions d&#39;annihilation de l&#39;âme sombre, l&#39;approbation de la fusion des deux âmes et la détermination de la validité de la volonté de l&#39;hôte d&#39;origine.</li><li><strong>Indépendance</strong> : le Comité d&#39;examen éthique exerce ses pouvoirs indépendamment, sans ingérence des organes administratifs et des individus.</li><li><strong>Procédure</strong> : l&#39;examen adopte un système d&#39;audience, rendant des décisions après avoir entendu les opinions de l&#39;hôte d&#39;origine (si capable de s&#39;exprimer), de l&#39;équipe de traitement, des membres de la famille, des représentants sociaux et de toutes les parties.</li></ul><h3 id="ii-matieres-devant-obligatoirement-subir-un-examen-ethique" tabindex="-1">(II) Matières devant obligatoirement subir un examen éthique <a class="header-anchor" href="#ii-matieres-devant-obligatoirement-subir-un-examen-ethique" aria-label="Permalink to &quot;(II) Matières devant obligatoirement subir un examen éthique&quot;">​</a></h3><p>Les matières suivantes doivent être examinées et approuvées par le Comité d&#39;examen éthique des deux âmes avant leur mise en œuvre :</p><ol><li>Mettre en œuvre une disposition annihilant l&#39;âme sombre pour les Entités de Remplacement Sombres aux troisième et quatrième stades.</li><li>Mettre en œuvre une opération de fusion des deux âmes sur les Entités de Remplacement Sombres.</li><li>Mettre en œuvre une opération de séparation des âmes sur les Entités de Remplacement Sombres.</li><li>Prendre des décisions de disposition finales pour les Entités de Remplacement Sombres dont la volonté de l&#39;hôte d&#39;origine est d&#39;abandonner le traitement.</li><li>Mettre en œuvre des plans de traitement susceptibles d&#39;endommager l&#39;âme maîtresse d&#39;origine.</li><li>Mener des recherches scientifiques impliquant l&#39;âme sur les Entités de Remplacement Sombres.</li><li>D&#39;autres matières impliquant des problèmes éthiques majeurs des deux âmes.</li></ol><h2 id="vi-droits-et-obligations-sociaux-des-entites-des-deux-ames" tabindex="-1">VI. Droits et Obligations Sociaux des Entités des Deux Âmes <a class="header-anchor" href="#vi-droits-et-obligations-sociaux-des-entites-des-deux-ames" aria-label="Permalink to &quot;VI. Droits et Obligations Sociaux des Entités des Deux Âmes&quot;">​</a></h2><h3 id="i-droits-sociaux" tabindex="-1">(I) Droits sociaux <a class="header-anchor" href="#i-droits-sociaux" aria-label="Permalink to &quot;(I) Droits sociaux&quot;">​</a></h3><p>Tant que l&#39;âme maîtresse d&#39;origine existe encore, l&#39;entité des deux âmes (Entité de Remplacement Sombre) jouit des droits sociaux suivants :</p><ol><li>Le droit de recevoir une sécurité de subsistance de base et des soins médicaux.</li><li>Le droit de recevoir une aide juridique et une consultation éthique.</li><li>Le droit de contacter parents et amis dans des conditions sûres et contrôlables.</li><li>Le droit de recevoir une éducation et de participer à des activités culturelles (dans les installations d&#39;isolement).</li><li>Le droit de faire appel et de demander un réexamen des décisions de disposition.</li></ol><h3 id="ii-obligations-et-restrictions-sociales" tabindex="-1">(II) Obligations et restrictions sociales <a class="header-anchor" href="#ii-obligations-et-restrictions-sociales" aria-label="Permalink to &quot;(II) Obligations et restrictions sociales&quot;">​</a></h3><p>L&#39;entité des deux âmes supporte simultanément les obligations et restrictions suivantes :</p><ol><li>L&#39;obligation d&#39;accepter le contrôle d&#39;isolement et le traitement.</li><li>L&#39;obligation de ne pas attaquer ou infecter d&#39;autres formes de vie (les contrevenants seront soumis à un contrôle plus strict).</li><li>L&#39;obligation de coopérer avec l&#39;évaluation d&#39;identification et la surveillance.</li><li>La liberté de mouvement est strictement limitée ; elle ne doit pas quitter l&#39;installation d&#39;isolement avant d&#39;être guérie.</li><li>Elle ne doit pas se livrer à la culture, à la propagation de l&#39;énergie sombre ou à d&#39;autres activités susceptibles d&#39;aggraver le remplacement.</li></ol><h2 id="vii-controverses-de-frontiere-dans-l-ethique-des-deux-ames" tabindex="-1">VII. Controverses de Frontière dans l&#39;Éthique des Deux Âmes <a class="header-anchor" href="#vii-controverses-de-frontiere-dans-l-ethique-des-deux-ames" aria-label="Permalink to &quot;VII. Controverses de Frontière dans l&#39;Éthique des Deux Âmes&quot;">​</a></h2><p>Il reste encore dans le domaine de l&#39;éthique des deux âmes des controverses de frontière qui n&#39;ont pas atteint de consensus et qui nécessitent une exploration continue dans la pratique :</p><ol><li><strong>Le problème du « péché originel » de l&#39;âme sombre</strong> : l&#39;âme de remplacement sombre est destructive dès la naissance. Cela signifie-t-il qu&#39;elle est intrinsèquement « mauvaise » ? Une âme sombre « bienveillante » est-elle possible ?</li><li><strong>La légitimité éthique de la fusion des âmes</strong> : la nouvelle âme produite par la fusion des deux âmes n&#39;est ni l&#39;hôte d&#39;origine ni l&#39;âme sombre. Comment déterminer le statut éthique de cette « troisième existence » ?</li><li><strong>La limite de l&#39;investissement en ressources</strong> : combien de ressources la société doit-elle investir pour sauver l&#39;âme maîtresse d&#39;origine au sein d&#39;une Entité de Remplacement Sombre ? Lorsque le coût du sauvetage est extrêmement élevé et le taux de réussite extrêmement faible, y a-t-il encore l&#39;obligation de faire des efforts maximaux ?</li><li><strong>La possibilité de réformer l&#39;âme sombre</strong> : l&#39;âme sombre peut-elle être réformée en une existence non destructive par l&#39;éducation, la rédemption, la transformation énergétique et d&#39;autres moyens ? Si oui, l&#39;âme sombre réformée devrait-elle obtenir des droits de la personnalité complets ?</li><li><strong>L&#39;équilibre entre prévention et vie privée</strong> : pour prévenir la génération d&#39;Entités de Remplacement Sombres, est-il permis de surveiller l&#39;exposition des êtres vivants à l&#39;Énergie des Abysses ? Cette surveillance viole-t-elle la vie privée de l&#39;âme ?</li></ol><p>Ces controverses sont continuellement étudiées par les institutions de recherche en éthique des deux âmes ; le Comité d&#39;examen éthique rend des décisions au cas par cas selon les circonstances spécifiques, et les conclusions pertinentes mettront continuellement à jour ces Directives.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Les Directives Éthiques des Deux Âmes sont une manifestation profonde de l&#39;éthique de la vie de la Civilisation Symbiotique de l&#39;Ancre. En établissant des principes fondamentaux tels que la dignité de l&#39;âme, la priorité de l&#39;âme d&#39;origine et le moindre préjudice, en déterminant les frontières des droits de la personnalité des deux âmes et en établissant des règles de pondération des conflits d&#39;intérêts et des mécanismes d&#39;examen éthique, elles fournissent un fondement éthique solide pour la gouvernance des Entités de Remplacement Sombres. L&#39;esprit central de l&#39;éthique des deux âmes est : même face à l&#39;ennemi le plus dangereux, ne pas abandonner la défense ferme de la dignité de la vie ; même sous la menace de sécurité la plus urgente, ne pas franchir la ligne de base éthique. C&#39;est précisément la marque fondamentale qui distingue la civilisation symbiotique de la civilisation prédatrice.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>57-黑暗置换体起源与本质 (Origine et Essence des Entités de Remplacement Sombres)</li><li>59-黑暗置换体四类分支处置 (Traitement des Quatre Branches des Entités de Remplacement Sombres)</li><li>48-司法体系与裁决机制 (Système Judiciaire et Mécanisme de Jugement)</li><li>40-共生宪法总纲 (Sommaire Général de la Constitution Symbiotique)</li></ul>',50)])])}const h=t(r,[["render",d]]);export{c as __pageData,h as default};
